/* Real Madrid DNA — royal white, championship gold, regal navy restraint */
.theme-real-madrid-dna {
  --bg: oklch(1.000 0 0);
  --surface: oklch(0.982 0.004 91.4);
  --surface-2: oklch(0.949 0.010 93.6);
  --fg: oklch(0.223 0.051 266.0);
  --fg-muted: oklch(0.612 0.031 272.2);
  --accent: oklch(0.297 0.096 261.4);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.729 0.115 86.3);
  --line: oklch(0.913 0.017 91.6);
  --success: oklch(0.523 0.135 144.2);
  --warning: oklch(0.838 0.170 83.6);
  --danger: oklch(0.543 0.174 29.7);
  --radius: 0.25rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Cinzel", Georgia, serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0.03em;
  --label-transform: uppercase;
  --label-tracking: 0.18em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-real-madrid-dna h1,
.theme-real-madrid-dna h2,
.theme-real-madrid-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-real-madrid-dna h1 { letter-spacing: 0.06em; }
.theme-real-madrid-dna h2 { border-bottom: 1px solid var(--accent-2); display: inline-block; padding-bottom: 0.25em; }
.theme-real-madrid-dna button { letter-spacing: 0.08em; text-transform: uppercase; font-size: 0.85em; }
.theme-real-madrid-dna h1 { color: #0f2a5c; }
.theme-real-madrid-dna h1::after { content: ""; display: block; height: 2px; width: 7rem; margin-top: 0.7rem; background: linear-gradient(90deg, #c7a24a, transparent); }
.theme-real-madrid-dna .label-caps { color: #c7a24a; }

/* depth */
.theme-real-madrid-dna thead th { color: var(--accent); text-transform: uppercase; letter-spacing: 0.14em; font-size: 0.75em; font-weight: 600; border-bottom: 3px double #c7a24a; }
.theme-real-madrid-dna td { border-bottom: 1px solid var(--line); }
.theme-real-madrid-dna tbody tr:hover { background: oklch(0.965 0.012 92); }
.theme-real-madrid-dna a { color: var(--accent); text-underline-offset: 3px; text-decoration-color: #c7a24a; }
.theme-real-madrid-dna a:hover { text-decoration-thickness: 2px; }
.theme-real-madrid-dna ::selection { background: oklch(0.297 0.096 261.4); color: oklch(1 0 0); }
.theme-real-madrid-dna input:focus-visible, .theme-real-madrid-dna select:focus-visible, .theme-real-madrid-dna textarea:focus-visible { outline: 1px solid #c7a24a; outline-offset: 2px; border-color: var(--accent); }
.theme-real-madrid-dna kbd { background: var(--surface); border: 1px solid #c7a24a; border-radius: var(--radius-sm); padding: 0.1em 0.45em; font-family: var(--font-mono); color: var(--accent); }
.theme-real-madrid-dna ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-real-madrid-dna ::-webkit-scrollbar-track { background: var(--surface); }
.theme-real-madrid-dna ::-webkit-scrollbar-thumb { background: oklch(0.297 0.096 261.4); border-radius: 5px; border: 2px solid var(--surface); }
.theme-real-madrid-dna ::-webkit-scrollbar-thumb:hover { background: #c7a24a; }
/* trophy-cabinet frame: hairline gold rule floated inside the border */
.theme-real-madrid-dna .themed-border { border-color: #c7a24a; outline: 1px solid oklch(0.729 0.115 86.3 / 40%); outline-offset: 3px; }
.theme-real-madrid-dna button:hover { box-shadow: 0 0 0 1px #c7a24a; }

/* alt mode: away kit (2026-27 real kit / NBA Association Edition) */
.theme-real-madrid-dna.alt-mode {
  --bg: oklch(0.274 0.043 165.2);
  --surface: oklch(0.317 0.050 165.8);
  --surface-2: oklch(0.362 0.056 166.3);
  --fg: oklch(0.951 0.015 94.2);
  --fg-muted: oklch(0.738 0.030 155.1);
  --accent: oklch(0.951 0.015 94.2);
  --accent-fg: oklch(0.274 0.043 165.2);
  --accent-2: oklch(0.729 0.115 86.3);
  --line: oklch(0.8 0.05 150 / 25%);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
}
.theme-real-madrid-dna.alt-mode h1 { color: #f2efe4; }
.theme-real-madrid-dna.alt-mode .label-caps { color: #c7a24a; }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
